argv:
$ErrorActionPreference='Continue'
$root=Join-Path $env:LOCALAPPDATA 'AgentOS'
$candidates=@(
  (Join-Path $root 'node.json'),
  (Join-Path $root 'config.json'),
  (Join-Path $root 'client.json'),
  (Join-Path $root 'realm.json')
)
$files=@()
foreach($f in $candidates){ if(Test-Path -LiteralPath $f){ $files += [ordered]@{path=$f;content=(Get-Content -Raw -LiteralPath $f)} } }
$envRows=@{}
Get-ChildItem Env: | Where-Object { $_.Name -match '(?i)AGENTOS|ONE|REALM|GATEWAY' } | ForEach-Object { $envRows[$_.Name]=$_.Value }
$procs=@(Get-CimInstance Win32_Process | Where-Object { $_.CommandLine -match '(?i)agentos_node\.client_cli\s+run' } | ForEach-Object { [ordered]@{pid=[int]$_.ProcessId;command_line=[string]$_.CommandLine} })
$targets=@()
foreach($text in @($files.content)+@($envRows.Values)+@($procs.command_line)){
  if($null -ne $text){ [regex]::Matches([string]$text,'https?://[^\s\"''<>]+') | ForEach-Object { $targets += $_.Value.TrimEnd('/','}',']',',') } }
}
$targets=@($targets | Select-Object -Unique)
$tests=@()
foreach($u in $targets){
  try{
    $uri=[uri]$u; $hostName=$uri.DnsSafeHost; $port=if($uri.IsDefaultPort){if($uri.Scheme -eq 'https'){443}else{80}}else{$uri.Port}
    $dns=$null; try{$dns=@([System.Net.Dns]::GetHostAddresses($hostName) | ForEach-Object {$_.IPAddressToString})}catch{$dns=@('DNS_ERROR:'+($_.Exception.Message))}
    $tcp=$false; $tcpError=$null; $sw=[Diagnostics.Stopwatch]::StartNew(); $client=New-Object Net.Sockets.TcpClient
    try{ $ar=$client.BeginConnect($hostName,$port,$null,$null); if($ar.AsyncWaitHandle.WaitOne(5000)){ $client.EndConnect($ar); $tcp=$true } else { $tcpError='timeout' } }catch{$tcpError=$_.Exception.Message}finally{$client.Close();$sw.Stop()}
    $httpStatus=$null; $httpError=$null; $httpMs=$null
    try{ $h=[Diagnostics.Stopwatch]::StartNew(); $r=Invoke-WebRequest -UseBasicParsing -Uri $u -Method Head -TimeoutSec 8 -ErrorAction Stop; $h.Stop(); $httpStatus=[int]$r.StatusCode; $httpMs=$h.ElapsedMilliseconds }catch{ if($h){$h.Stop();$httpMs=$h.ElapsedMilliseconds}; $httpError=$_.Exception.Message; if($_.Exception.Response){try{$httpStatus=[int]$_.Exception.Response.StatusCode}catch{}} }
    $tests += [ordered]@{url=$u;host=$hostName;port=$port;dns=$dns;tcp=$tcp;tcp_error=$tcpError;tcp_ms=$sw.ElapsedMilliseconds;http_status=$httpStatus;http_error=$httpError;http_ms=$httpMs}
  }catch{ $tests += [ordered]@{url=$u;parse_error=$_.Exception.Message} }
}
[ordered]@{schema='agentos.node-transport-diagnostic/v1';observed_at=(Get-Date).ToUniversalTime().ToString('o');files=$files;env=$envRows;client_processes=$procs;targets=$targets;tests=$tests} | ConvertTo-Json -Depth 8 -Compress
